function _dist(AC, amt = 0.5) {
  const s = AC.createWaveShaper();
  const n = 256, c = new Float32Array(n), k = amt * 100;
  for (let i = 0; i < n; i++) { const x = (i*2)/n-1; c[i]=((Math.PI+k)*x)/(Math.PI+k*Math.abs(x)); }
  s.curve = c; s.oversample = '4x'; return s;
}

